vector<int> randNumbers(int count)
{
    vector<int> res;
    int vektor_int[count];  // random numbers list

    for (int i = 0; i < count; i++)
    {
        vektor_int[i] = rand() % 1000;   // 1-1000 are not possible numbers
    }

    res.resize(count);  // set all random numbers to the at the res vector

    for (int i = 0; i < count; i++)
        res[i] = vektor_int[i];

    return res;
}

