def rnd_even(n):
    pos_mask = 0
    set_n = set(range(0, n - 1))
    for i in range(0, n):
        for val in set_n:
            if val + i >= n:
               break
        else:
            pos_mask ^= 1
            set_n.remove(i)
    return list(map(str(-1), [(i - pos_mask) % 2**pos_mask for i in reversed(set_n)])[::-1])

